-- Resources slice 5: the guide backfill.
--
-- Every enabled tool that had no guide gets them here — Editorial Planning,
-- Audience Listening, and Academic Partnerships — with a release note linking
-- each set. Written through the release helpers
-- (20260928200000_resources_release_helpers.sql), the way every release
-- migration writes Resources content from now on (CLAUDE.md, "Resources stay
-- in step with the code"). Guides describe the screens as they are today.
--
-- Remote Interview and Editorial Inquiry are disabled in the registry and get
-- their guides when they're turned on. Generated; edit the text, not the JSON
-- shape — src/lib/resources/release-content.test.ts checks every body.

select private.rc_release_guide(
  p_slug => 'editorial-submit-a-pitch',
  p_tool_key => 'editorial-planning',
  p_title => 'Submit a pitch',
  p_summary => 'Put a story idea in the backlog and follow how it''s decided.',
  p_screen_keys => array['editorial.backlog', 'editorial.pitch'],
  p_sort_order => 10,
  p_version_note => 'Written for the Resources backfill',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every story idea starts as a pitch in the backlog. An editor picks pitches from the backlog for a weekly planning meeting, where reviewers score them and the editor records a decision."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Submit one"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the Backlog tab, select "},{"type":"text","text":"New pitch","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Give it a title — one line that says what the story is — and fill in the fields below it. Fields marked with an asterisk are required."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose a "},{"type":"text","text":"Primary coverage pillar","marks":[{"type":"bold"}]},{"type":"text","text":". If you choose one of the station's pillars, say how the story contributes to sustained coverage of it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Submit pitch","marks":[{"type":"bold"}]},{"type":"text","text":". You land on the pitch's own page."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit it"}]},{"type":"paragraph","content":[{"type":"text","text":"You can keep editing your pitch with "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" until an editor adds it to a meeting's slate. While that meeting is scoring, edits are locked; they reopen if the pitch comes back to the backlog."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Follow it"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Backlog has four views: "},{"type":"text","text":"Open","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Stale","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Assigned","marks":[{"type":"bold"}]},{"type":"text","text":", and "},{"type":"text","text":"Archived","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A pitch is stale when it has gone 90 days without a review, or has been deferred three times. Editors can archive stale pitches in bulk from the Stale view."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The pitch page's "},{"type":"text","text":"Review history","marks":[{"type":"bold"}]},{"type":"text","text":" lists each meeting that discussed it, with its scores, reviewers' comments, and the decision."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once a pitch is assigned, the reporter or an editor can start its story plan from the pitch page."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'editorial-run-a-planning-meeting',
  p_tool_key => 'editorial-planning',
  p_title => 'Run a planning meeting',
  p_summary => 'Build a slate, score it independently, then decide from the ranked agenda.',
  p_screen_keys => array['editorial.meeting'],
  p_sort_order => 20,
  p_version_note => 'Written for the Resources backfill',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A planning meeting moves through three stages: "},{"type":"text","text":"Scoring open","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Agenda","marks":[{"type":"bold"}]},{"type":"text","text":", and "},{"type":"text","text":"Concluded","marks":[{"type":"bold"}]},{"type":"text","text":". Editors run it; reviewers and editors score; contributors can follow along."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Set it up (editors)"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the Meetings tab, choose the meeting date and a rubric profile, then select "},{"type":"text","text":"Create meeting","marks":[{"type":"bold"}]},{"type":"text","text":". Pick Immediate / Emerging News when the slate is mostly urgent coverage."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the meeting. Under "},{"type":"text","text":"+ Add pitch","marks":[{"type":"bold"}]},{"type":"text","text":", choose a pitch from the backlog and select "},{"type":"text","text":"Add to slate","marks":[{"type":"bold"}]},{"type":"text","text":". Repeat for each pitch."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Score the slate (reviewers and editors)"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open each pitch on the slate. "},{"type":"text","text":"Show pitch details","marks":[{"type":"bold"}]},{"type":"text","text":" expands the full pitch."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose a score for each criterion. Hover a number to read what it means. Institutional modifiers are optional."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose a recommendation, flag any concerns, and add a comment if it helps the room. Select "},{"type":"text","text":"Save review","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Scoring is independent: nobody sees anyone else's scores or comments until the editor closes scoring."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Decide (editors)"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Close scoring & build agenda","marks":[{"type":"bold"}]},{"type":"text","text":". The slate is ranked by score."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A red "},{"type":"text","text":"Split","marks":[{"type":"bold"}]},{"type":"text","text":" badge means reviewers disagree — worth discussing. Open "},{"type":"text","text":"Scores, recommendations & comments","marks":[{"type":"bold"}]},{"type":"text","text":" to see why."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For each pitch, choose "},{"type":"text","text":"Assign","marks":[{"type":"bold"}]},{"type":"text","text":" (pick the reporter first), "},{"type":"text","text":"Defer","marks":[{"type":"bold"}]},{"type":"text","text":" to keep it in the backlog, or "},{"type":"text","text":"Archive","marks":[{"type":"bold"}]},{"type":"text","text":". Select "},{"type":"text","text":"Change","marks":[{"type":"bold"}]},{"type":"text","text":" to revise a decision."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Conclude meeting","marks":[{"type":"bold"}]},{"type":"text","text":". Any pitch still undecided is deferred. A concluded meeting is a permanent record."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'editorial-configure-form-and-rubric',
  p_tool_key => 'editorial-planning',
  p_title => 'Configure the pitch form and rubric',
  p_summary => 'Editors choose what writers are asked and what reviewers score.',
  p_screen_keys => array['editorial.settings'],
  p_sort_order => 30,
  p_version_note => 'Written for the Resources backfill',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Settings is for editors. It has three parts: "},{"type":"text","text":"Submission form","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Pillars","marks":[{"type":"bold"}]},{"type":"text","text":", and "},{"type":"text","text":"Rubric","marks":[{"type":"bold"}]},{"type":"text","text":". Retired entries stay on the pitches and scores that used them, so nothing changed here rewrites history."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Submission form"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"+ Add field","marks":[{"type":"bold"}]},{"type":"text","text":" to add a question to the pitch form. A field's type is fixed once it exists; its label, help text, options, and whether it's required can change later."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reorder fields with the arrows. Retire a field you no longer need; restore it any time."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Pillars"}]},{"type":"paragraph","content":[{"type":"text","text":"Pillars are the station's coverage priorities. Each has a guiding question, shown to writers on the pitch form. Retire a pillar to take it off the form; a retired pillar can be deleted."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Rubric"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Criteria belong to a rubric profile. Core criteria are weighted and averaged; the weights in a profile should add up to 100. Modifiers are scored separately and never count toward the core average."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each criterion can carry anchored descriptions — what each score means — which reviewers see when they hover a score."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A weight change applies to future scoring only. The scoring scale and the modifier threshold are set at the bottom of the page."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'audience-listening-publish-a-query',
  p_tool_key => 'audience-listening',
  p_title => 'Create and publish a query',
  p_summary => 'Ask the public up to five recorded questions from a story or a link.',
  p_screen_keys => array['audience-listening.queries', 'audience-listening.query'],
  p_sort_order => 10,
  p_version_note => 'Written for the Resources backfill',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A query is a recorded callout: up to five questions a listener answers out loud, from a standalone page or an embed in a story."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create it"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"New query","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Give it an internal title (the newsroom's name for it), a public title, and a public introduction saying why you're asking and what you'll do with the answers. Select "},{"type":"text","text":"Create query","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the "},{"type":"text","text":"Questions","marks":[{"type":"bold"}]},{"type":"text","text":" tab, add each question: the prompt, optional guidance, a maximum length, and whether it's required."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the "},{"type":"text","text":"Settings","marks":[{"type":"bold"}]},{"type":"text","text":" tab, choose which details to ask participants for, the consent and attribution questions, and optional opening and closing dates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Preview","marks":[{"type":"bold"}]},{"type":"text","text":" to walk through it as a participant would. Nothing is submitted."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish it"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Open for responses","marks":[{"type":"bold"}]},{"type":"text","text":". Until then the public link doesn't work, even for someone who has it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the "},{"type":"text","text":"Share","marks":[{"type":"bold"}]},{"type":"text","text":" tab, copy the public link for newsletters and social posts, or the Grove embed code to paste into a Grove Responsive Embed element unchanged. If you add questions later, copy the embed code again."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once a query has submissions, question wording can still change, but questions can't be removed or reordered. Each answer keeps the exact question it was asked."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Close query","marks":[{"type":"bold"}]},{"type":"text","text":" to stop new responses. Anyone already recording can still finish and submit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A query can be deleted only before it has any submissions. After that, archive it."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'audience-listening-review-submissions',
  p_tool_key => 'audience-listening',
  p_title => 'Review submissions and send answers to transcription',
  p_summary => 'Read consent, review each answer, and hand answers to Sourcework.',
  p_screen_keys => array['audience-listening.query'],
  p_sort_order => 20,
  p_version_note => 'Written for the Resources backfill',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Responses arrive on the query's "},{"type":"text","text":"Submissions","marks":[{"type":"bold"}]},{"type":"text","text":" tab, one row per participant. Open a row to review everything that person sent."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review a submission"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Read the "},{"type":"text","text":"Consent and attribution","marks":[{"type":"bold"}]},{"type":"text","text":" card first. Contact, identification by name, and anonymity are three separate answers; read all three before using anything."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Listen to each answer. The question shown is the wording the participant was asked, even if it has changed since."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review each answer, and then the submission as a whole, with "},{"type":"text","text":"Mark reviewed","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Flag","marks":[{"type":"bold"}]},{"type":"text","text":", or "},{"type":"text","text":"Reject","marks":[{"type":"bold"}]},{"type":"text","text":". Add internal notes as you go."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Send an answer to transcription"}]},{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Send to transcription","marks":[{"type":"bold"}]},{"type":"text","text":" on an answer. It becomes a Sourcework project, and the answer then links to it. If a handoff fails, select "},{"type":"text","text":"Retry transcription","marks":[{"type":"bold"}]},{"type":"text","text":". Sending needs Sourcework access as well."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Automatic transcription"}]},{"type":"paragraph","content":[{"type":"text","text":"When a query's transcription setting is Automatic, each answer is queued as it arrives. A staff member still sends the queue: select "},{"type":"text","text":"Send queued answers","marks":[{"type":"bold"}]},{"type":"text","text":" on the Submissions tab. Nothing is transcribed entirely unattended."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'academic-partnerships-work-the-pipeline',
  p_tool_key => 'academic-partnerships',
  p_title => 'Work an inquiry through the pipeline',
  p_summary => 'Move faculty inquiries through the seven stages, or close them with a disposition.',
  p_screen_keys => array['academic-partnerships.pipeline', 'academic-partnerships.submission'],
  p_sort_order => 10,
  p_version_note => 'Written for the Resources backfill',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Faculty inquiries from the public form arrive in the "},{"type":"text","text":"New","marks":[{"type":"bold"}]},{"type":"text","text":" column of the Pipeline. From there they move through Reviewing, Meeting Requested, Scoping, Approved, Active, and Completed."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Move an inquiry"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Drag the card to another column."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Or use the stage menu under the card. It works by keyboard, screen reader, and touch."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the inquiry's own page, change its "},{"type":"text","text":"Stage","marks":[{"type":"bold"}]},{"type":"text","text":" and select "},{"type":"text","text":"Save","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Work the inquiry"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select the card to open it. The original response is at the top."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set an "},{"type":"text","text":"Owner","marks":[{"type":"bold"}]},{"type":"text","text":" so the team knows who has it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record an "},{"type":"text","text":"Assessment","marks":[{"type":"bold"}]},{"type":"text","text":" — overall fit, capacity, and timing — and a "},{"type":"text","text":"Next action","marks":[{"type":"bold"}]},{"type":"text","text":" with a date. The date shows on the card."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add internal notes. Everything is recorded in the inquiry's "},{"type":"text","text":"Activity","marks":[{"type":"bold"}]},{"type":"text","text":" log."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Close one without completing it"}]},{"type":"paragraph","content":[{"type":"text","text":"Under "},{"type":"text","text":"Disposition","marks":[{"type":"bold"}]},{"type":"text","text":", choose Deferred, Declined, Withdrawn, or Archived and select "},{"type":"text","text":"Apply","marks":[{"type":"bold"}]},{"type":"text","text":". Every choice except Archived needs a reason. The inquiry leaves the board but keeps the stage it reached; find it on "},{"type":"text","text":"All submissions","marks":[{"type":"bold"}]},{"type":"text","text":", and select "},{"type":"text","text":"Reopen","marks":[{"type":"bold"}]},{"type":"text","text":" to bring it back."}]},{"type":"paragraph","content":[{"type":"text","text":"Coordinators can also delete an inquiry permanently from the Danger zone at the bottom of its page."}]}]}$body$
);

